            margin: 0 0 14px !important;
            padding: 15px 18px !important;
            border: none !important;
            border-radius: 15px !important;
            background: linear-gradient( 115deg, #193e66, #255485 ) !important;
            color: white !important;
            font-size: 12px !important;
            box-sizing: border-box;
        }


            body.sm-app .historial-sectores-orbita
            .historial-resumen-filtros strong {
                color: white !important;
                font-size: 17px;
                margin-left: 4px;
            }


        body.sm-app .historial-sectores-orbita
        .sector-resumen-nombre {
            display: inline-flex;
            align-items: center;
            gap: 5px;
            padding: 6px 10px;
            border-radius: 999px;
            background: rgba(255, 255, 255, 0.12);
            border: 1px solid rgba(255, 255, 255, 0.2);
            color: white;
            font-weight: 700;
        }


        /* =====================================
           CONTENEDOR DE TABLA
           SCROLL VERTICAL INDEPENDIENTE
           ===================================== */

        body.sm-app .historial-sectores-orbita
        .tabla-wrap {
            display: block !important;
            position: relative !important;
            width: 100% !important;
            max-width: 100% !important;
            height: auto !important;
            max-height: clamp( 280px, 56vh, 680px ) !important;
            overflow-y: auto !important;
            overflow-x: auto !important;
            overscroll-behavior-y: contain;
            scrollbar-gutter: stable;
            border: 1px solid #ccdbec;
