﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "ModuloMovimientoHistorial"; ViewData["SmFamily"] = "movements"; }
@using Microsoft.AspNetCore.Http

@{
    ViewData["Title"] = "Movimientos e Historial";

    ViewData["TituloBarra"] =
        "Seleccione Historial";


    // =========================================================
    // OBTENER PERMISOS DEL USUARIO
    // =========================================================

    string permisosTexto =
        Context.Session.GetString("Permisos") ?? "";


    var permisos =
        permisosTexto
            .Split(
                '|',
                StringSplitOptions.RemoveEmptyEntries
            )
            .ToList();


    Func<string, bool> TienePermiso =
        permiso =>
            permisos.Any(
                p => p.Equals(
                    permiso,
                    StringComparison.OrdinalIgnoreCase
                )
            );


    // =========================================================
    // PERMISOS DE LOS HISTORIALES
    // =========================================================

    bool puedeConsultarHistorial =
        TienePermiso(
            "Consultar historial"
        );


    bool puedeGestionarUsuarios =
        TienePermiso(
            "Gestionar usuarios y permisos"
        );
}


<style>

    /* CONTENEDOR */

    .submenu-contenedor {
        width: 90%;
        max-width: 1100px;
        margin: 5px auto;
        text-align: center;
    }



    /* TITULO */

    .submenu-titulo {
