        .submenu-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 14px 30px rgba(15, 91, 150, 0.25);
            color: #17324d;
        }



    /* ICONO */

    .submenu-icono {
        margin-bottom: 12px;
        font-size: 42px;
    }



    /* TITULO TARJETA */

    .submenu-card-titulo {
        margin-bottom: 8px;
        color: #087bc2;
        font-size: 21px;
        font-weight: 700;
    }


    .submenu-card p {
        margin: 0;
        color: #687b89;
        font-size: 14px;
    }



    /* BOTON VOLVER */

