        margin-top: 35px;
        text-align: center;
    }


    .btn-volver-submenu {
        display: inline-block;
        padding: 11px 20px;
        background: #0b8f9c;
        color: white;
        border-radius: 7px;
        text-decoration: none;
        font-weight: 600;
    }


        .btn-volver-submenu:hover {
            background: #087580;
            color: white;
        }



    /* RESPONSIVE */

    @@media (max-width: 900px) {

        .submenu-grid {
            grid-template-columns: 1fr;
        }


        .submenu-contenedor {
            width: 94%;
        }
    }


    @@media (max-width: 600px) {

        .submenu-titulo {
            font-size: 27px;
        }


        .submenu-card {
            min-height: 170px;
            padding: 25px;
        }


        .submenu-icono {
