﻿@model LoginSARMedix.ViewComponents.AlertasViewModel

<div class="alertas-sarmedix"
     id="alertasSarmedix">

    <!-- CAMPANA -->

    <button type="button"
            class="alertas-boton"
            id="botonAlertasSarmedix"
            onclick="alternarAlertasSarmedix(event)"
            aria-label="Ver alertas"
            aria-expanded="false" data-orbit-action="icon">

        <svg viewBox="0 0 24 24"
             aria-hidden="true"
             class="alertas-campana-icono">

            <path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9">
            </path>

            <path d="M10 21h4">
            </path>

        </svg>


        @if (Model.Total > 0)
        {
            <span class="alertas-contador">

                @(Model.Total > 99
                    ? "99+"
                    : Model.Total.ToString())

            </span>
        }

    </button>



    <!-- PANEL -->

    <div class="alertas-panel"
         id="panelAlertasSarmedix">


        <!-- CABECERA -->

        <div class="alertas-panel-cabecera">

            <div>

                <span class="alertas-panel-etiqueta">
                    Inventario
                </span>

                <h3>
                    Alertas
                </h3>

            </div>


            @if (Model.Total > 0)
            {
                <span class="alertas-total">

                    @Model.Total

                </span>
            }

        </div>



        <!-- RESUMEN -->

        @if (Model.Total > 0)
        {
            <div class="alertas-resumen">


                <!-- VENCIDOS -->

                <div class="alertas-resumen-item
                            alertas-resumen-vencidos">

                    <strong>
                        @Model.TotalVencidos
                    </strong>

                    <span>
                        Vencidos
                    </span>

                </div>



                <!-- STOCK -->

                <div class="alertas-resumen-item
                            alertas-resumen-stock">

                    <strong>
                        @Model.TotalStockBajo
                    </strong>

                    <span>
                        Stock bajo
                    </span>

                </div>



                <!-- PROXIMOS -->

                <div class="alertas-resumen-item
                            alertas-resumen-proximos">

                    <strong>
                        @Model.TotalProximos
                    </strong>

                    <span>
                        Por vencer
                    </span>

                </div>


            </div>
        }



        <!-- SIN ALERTAS -->

        @if (Model.Total == 0)
        {
            <div class="alertas-vacio">


                <div class="alertas-vacio-icono">

                    ✓

                </div>


                <strong>
                    Sin alertas activas
                </strong>


                <span>
                    El inventario no presenta alertas
                    de stock o vencimiento.
                </span>


            </div>
        }



        <!-- LISTADO -->

        @if (Model.Total > 0)
        {
            <div class="alertas-listado">


                @foreach (var alerta in Model.Alertas)
                {
                    string claseTipo =
    alerta.Tipo switch
    {
        "vencido" =>
            "alerta-vencido",

        "stock" =>
            "alerta-stock",

        "proximo" =>
            "alerta-proximo",

        "ubicacion" =>
            "alerta-vencido",

        _ =>
            ""
    };


                    string textoTipo =
    alerta.Tipo switch
    {
        "vencido" =>
            "Vencido",

        "stock" =>
            "Stock bajo",

        "proximo" =>
            "Próximo a vencer",

        "ubicacion" =>
            "Ubicación",

        _ =>
            "Alerta"
    };

string icono =
    alerta.Tipo switch
    {
        "vencido" =>
            "!",

        "stock" =>
            "↓",

        "proximo" =>
            "◷",

        "ubicacion" =>
            "!",

        _ =>
            "!"
    };


                    <!-- ALERTA CON DESTINO -->

                    @if (!string.IsNullOrWhiteSpace(
                            alerta.UrlDestino))
                    {
                        <a href="@alerta.UrlDestino"
                           class="alertas-item
                                  alertas-item-enlace
                                  @claseTipo"
                           title="@alerta.TextoDestino" data-orbit-action="navigation">


                            <div class="alertas-item-icono">

                                @icono

                            </div>



                            <div class="alertas-item-contenido">


                                <div class="alertas-item-superior">

                                    <strong class="alertas-item-titulo">

                                        @alerta.Titulo

                                    </strong>


                                    <span class="alertas-item-tipo">

                                        @textoTipo

                                    </span>

                                </div>


                                <span class="alertas-item-detalle">

                                    @alerta.Detalle

                                </span>



                                <span class="alertas-item-destino">

                                    @alerta.TextoDestino

                                    <span>
                                        →
                                    </span>

                                </span>


                            </div>



                            <div class="alertas-item-flecha"
                                 aria-hidden="true">

                                ›

                            </div>


                        </a>
                    }



                    <!-- ALERTA SIN DESTINO -->

                    @if (string.IsNullOrWhiteSpace(
                            alerta.UrlDestino))
                    {
                        <div class="alertas-item
                                    @claseTipo">


                            <div class="alertas-item-icono">

                                @icono

                            </div>



                            <div class="alertas-item-contenido">


                                <div class="alertas-item-superior">

                                    <strong class="alertas-item-titulo">

                                        @alerta.Titulo

                                    </strong>


                                    <span class="alertas-item-tipo">

                                        @textoTipo

                                    </span>

                                </div>


                                <span class="alertas-item-detalle">

                                    @alerta.Detalle

                                </span>


                            </div>


                        </div>
                    }
                }


            </div>
        }



        <!-- PIE -->

        <div class="alertas-panel-pie">

            Las alertas se actualizan automáticamente
            con el inventario actual.

        </div>


    </div>

</div>



<style>

    /* CONTENEDOR */

    .alertas-sarmedix {
        position: relative;

        display: flex;

        align-items: center;

        justify-content: center;
    }



    /* CAMPANA */

    .alertas-boton {
        position: relative;

        width: 42px;

        height: 42px;

        min-width: 42px;

        padding: 0;

        display: flex;

        align-items: center;

        justify-content: center;

        border:
            1px solid
            rgba(255, 255, 255, 0.30);

        border-radius: 10px;

        background:
            rgba(255, 255, 255, 0.11);

        color: white;

        cursor: pointer;

        transition:
            background-color 0.2s ease,
            border-color 0.2s ease,
            transform 0.15s ease;
    }


    .alertas-boton:hover {
        background:
            rgba(255, 255, 255, 0.20);

        border-color:
            rgba(255, 255, 255, 0.60);

        transform:
            translateY(
                -1px
            );
    }


    .alertas-boton:focus {
        outline:
            2px solid
            rgba(255, 255, 255, 0.55);

        outline-offset: 2px;
    }


    .alertas-campana-icono {
        width: 21px;

        height: 21px;

        fill: none;

        stroke: currentColor;

        stroke-width: 1.8;

        stroke-linecap: round;

        stroke-linejoin: round;
    }



    /* CONTADOR */

    .alertas-contador {
        position: absolute;

        top: -7px;

        right: -7px;

        min-width: 20px;

        height: 20px;

        padding:
            0
            5px;

        display: flex;

        align-items: center;

        justify-content: center;

        box-sizing: border-box;

        border:
            2px solid
            #0f5278;

        border-radius: 999px;

        background: #dc3545;

        color: white;

        font-size: 9px;

        font-weight: 800;

        line-height: 1;
    }



    /* PANEL */

    .alertas-panel {
        position: absolute;

        top: calc(100% + 13px);

        right: 0;

        z-index: 10000;

        width: 410px;

        max-width:
            calc(
                100vw
                -
                30px
            );

        display: none;

        overflow: hidden;

        border:
            1px solid
            #dce7ec;

        border-radius: 14px;

        background: white;

        color: #263b47;

        box-shadow:
            0 18px 45px
            rgba(0, 38, 64, 0.25);
    }


    .alertas-panel.abierto {
        display: block;
    }



    /* FLECHA DEL PANEL */

    .alertas-panel::before {
        content: "";

        position: absolute;

        top: -7px;

        right: 14px;

        width: 14px;

        height: 14px;

        border-top:
            1px solid
            #dce7ec;

        border-left:
            1px solid
            #dce7ec;

        background: white;

        transform:
            rotate(
                45deg
            );
    }



    /* CABECERA */

    .alertas-panel-cabecera {
        position: relative;

        padding:
            18px
            18px
            14px;

        display: flex;

        align-items: center;

        justify-content: space-between;

        gap: 14px;

        border-bottom:
            1px solid
            #e9eff2;
    }


    .alertas-panel-cabecera > div {
        display: flex;

        flex-direction: column;

        gap: 2px;
    }


    .alertas-panel-etiqueta {
        color: #1198a5;

