            color 0.16s ease;
    }



    /* SIN ALERTAS */

    .alertas-vacio {
        padding:
            35px
            25px;

        display: flex;

        flex-direction: column;

        align-items: center;

        gap: 6px;

        text-align: center;
    }


    .alertas-vacio-icono {
        width: 42px;

        height: 42px;

        margin-bottom: 4px;

        display: flex;

        align-items: center;

        justify-content: center;

        border-radius: 50%;

        background: #eaf4f7;

        color: #087f8b;

        font-size: 20px;

        font-weight: 800;
    }


    .alertas-vacio strong {
        color: #244759;

        font-size: 13px;
    }


    .alertas-vacio span {
        max-width: 250px;

        color: #758791;

        font-size: 10px;

        line-height: 1.5;
    }



    /* PIE */

    .alertas-panel-pie {
        padding:
            10px
            15px;

        border-top:
            1px solid
            #e8eef1;

        background: #f7fafb;

        color: #7b8d96;

        font-size: 9px;

        text-align: center;
    }



    /* RESPONSIVE */

    @@media (max-width: 620px) {

        .alertas-panel {
            position: fixed;

            top: 78px;

            right: 10px;

            left: 10px;

            width: auto;

            max-width: none;
        }


        .alertas-panel::before {
            display: none;
        }


        .alertas-resumen {
            grid-template-columns:
                repeat(
                    3,
                    minmax(
                        0,
                        1fr
                    )
                );
        }

    }

</style>



<script>

    // ABRIR / CERRAR ALERTAS

    function alternarAlertasSarmedix(
        evento
    ) {

        if (evento) {

            evento.stopPropagation();

        }


        const panel =
            document.getElementById(
                "panelAlertasSarmedix"
            );


        const boton =
            document.getElementById(
                "botonAlertasSarmedix"
            );


        if (
            !panel
            ||
            !boton
        ) {

            return;

        }


        const abierto =
            panel.classList.contains(
                "abierto"
            );


        if (abierto) {

            panel.classList.remove(
                "abierto"
            );


            boton.setAttribute(
                "aria-expanded",
                "false"
            );

        }
        else {

            panel.classList.add(
                "abierto"
            );


            boton.setAttribute(
                "aria-expanded",
                "true"
            );

        }

    }



    // EVITAR QUE EL PANEL SE CIERRE AL HACER CLIC DENTRO

    document
        .getElementById(
            "panelAlertasSarmedix"
        )
        ?.addEventListener(
            "click",
            function (
                evento
            ) {

                evento.stopPropagation();

            }
        );



    // CERRAR AL HACER CLIC FUERA

    document.addEventListener(
        "click",
        function () {

            const panel =
                document.getElementById(
                    "panelAlertasSarmedix"
                );


            const boton =
                document.getElementById(
                    "botonAlertasSarmedix"
                );


            if (
                panel
                &&
                panel.classList.contains(
                    "abierto"
                )
            ) {

                panel.classList.remove(
                    "abierto"
                );


                boton
                    ?.setAttribute(
                        "aria-expanded",
                        "false"
                    );

            }

        }
    );



    // CERRAR CON ESC

    document.addEventListener(
        "keydown",
        function (
            evento
        ) {

            if (
                evento.key
                !==
                "Escape"
            ) {

                return;

            }


            const panel =
                document.getElementById(
                    "panelAlertasSarmedix"
                );


            const boton =
                document.getElementById(
                    "botonAlertasSarmedix"
                );


            panel
                ?.classList
                .remove(
                    "abierto"
                );


            boton
                ?.setAttribute(
                    "aria-expanded",
                    "false"
                );

        }
    );

</script>

LoginSARMedix/Views/Shared/Error.cshtml.text:
﻿@* SM-ORBITA-METADATA *@
@{ ViewData["SmScreen"] = "Error"; ViewData["SmFamily"] = "error"; }
@model ErrorViewModel
@{
    ViewData["Title"] = "Error";
}

<section class="orbit-error-panel"><span class="orbit-eyebrow">ÓRBITA / ESTADO DEL SISTEMA</span><h1 class="text-danger">Error.</h1>
<h2 class="text-danger">An error occurred while processing your request.</h2>

@if (Model.ShowRequestId)
{
    <p>
        <strong>Request ID:</strong> <code>@Model.RequestId</code>
    </p>
}

<h3>Development Mode</h3>
<p>
    Swapping to <strong>Development</strong> environment will display more detailed information about the error that occurred.
</p>
<p>
    <strong>The Development environment shouldn't be enabled for deployed applications.</strong>
    It can result in displaying sensitive information from exceptions to end users.
    For local debugging, enable the <strong>Development</strong> environment by setting the <strong>ASPNETCORE_ENVIRONMENT</strong> environment variable to <strong>Development</strong>
    and restarting the app.
</p>
</section>

